use crate::error::{Error, Result};
use crate::config::Config;
use ibapi::prelude::*;
use std::sync::Arc;
use tokio::sync::RwLock;
use std::time::Duration;
use tracing::{info, warn, error, debug};

#[derive(Debug, Clone)]
pub enum ConnectionStatus {
    Disconnected,
    Connecting,
    Connected,
    Error(String),
}

pub struct ConnectionManager {
    client: Option<Arc<RwLock<Client>>>,
    config: Config,
    status: Arc<RwLock<ConnectionStatus>>,
    reconnect_attempts: u32,
    max_reconnect_attempts: u32,
}

impl ConnectionManager {
    pub fn new(config: Config) -> Self {
        Self {
            client: None,
            config,
            status: Arc::new(RwLock::new(ConnectionStatus::Disconnected)),
            reconnect_attempts: 0,
            max_reconnect_attempts: 5,
        }
    }

    pub async fn connect(&mut self) -> Result<()> {
        *self.status.write().await = ConnectionStatus::Connecting;
        info!("Attempting to connect to TWS at {}", self.config.connection_url());

        match self.attempt_connection().await {
            Ok(client) => {
                info!("Successfully connected to TWS");
                self.client = Some(Arc::new(RwLock::new(client)));
                *self.status.write().await = ConnectionStatus::Connected;
                self.reconnect_attempts = 0;
                Ok(())
            }
            Err(e) => {
                error!("Failed to connect to TWS: {}", e);
                *self.status.write().await = ConnectionStatus::Error(e.to_string());
                Err(e)
            }
        }
    }

    async fn attempt_connection(&self) -> Result<Client> {
        Client::connect(&self.config.connection_url(), self.config.client_id)
            .map_err(|e| Error::Connection(format!("Failed to connect to TWS: {}", e)))
    }

    pub async fn reconnect(&mut self) -> Result<()> {
        if self.reconnect_attempts >= self.max_reconnect_attempts {
            return Err(Error::Connection(
                format!("Max reconnection attempts ({}) reached", self.max_reconnect_attempts)
            ));
        }

        self.reconnect_attempts += 1;
        let delay = self.calculate_backoff_delay();

        warn!("Reconnection attempt {} of {}. Waiting {:?} before retry...", 
              self.reconnect_attempts, self.max_reconnect_attempts, delay);

        tokio::time::sleep(delay).await;
        self.connect().await
    }

    fn calculate_backoff_delay(&self) -> Duration {
        let base_delay = 2u64;
        let max_delay = 60u64;
        let delay = base_delay.pow(self.reconnect_attempts.min(6)) as u64;
        Duration::from_secs(delay.min(max_delay))
    }

    pub async fn disconnect(&mut self) -> Result<()> {
        if let Some(client_arc) = &self.client {
            let client = client_arc.read().await;
            info!("Disconnecting from TWS");
            // Note: ibapi Client doesn't have explicit disconnect, it disconnects on drop
            drop(client);
        }

        self.client = None;
        *self.status.write().await = ConnectionStatus::Disconnected;
        info!("Disconnected from TWS");
        Ok(())
    }

    pub async fn status(&self) -> ConnectionStatus {
        self.status.read().await.clone()
    }

    pub async fn is_connected(&self) -> bool {
        matches!(*self.status.read().await, ConnectionStatus::Connected)
    }

    pub fn client(&self) -> Option<Arc<RwLock<Client>>> {
        self.client.clone()
    }

    pub async fn health_check(&self) -> Result<bool> {
        if !self.is_connected().await {
            return Ok(false);
        }

        if let Some(client_arc) = &self.client {
            let client = client_arc.read().await;
            // Try to get server time as a health check
            match client.server_time() {
                Ok(_) => {
                    debug!("Health check passed");
                    Ok(true)
                }
                Err(e) => {
                    warn!("Health check failed: {}", e);
                    Ok(false)
                }
            }
        } else {
            Ok(false)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_backoff_delay_calculation() {
        let config = Config {
            tws_host: "127.0.0.1".to_string(),
            tws_port: 7500,
            client_id: 100,
            paper_trading: true,
            log_level: "info".to_string(),
        };

        let manager = ConnectionManager::new(config);

        // Test exponential backoff
        assert_eq!(manager.calculate_backoff_delay(), Duration::from_secs(2));
    }

    #[tokio::test]
    async fn test_connection_status_transitions() {
        let config = Config {
            tws_host: "127.0.0.1".to_string(),
            tws_port: 7500,
            client_id: 100,
            paper_trading: true,
            log_level: "info".to_string(),
        };

        let manager = ConnectionManager::new(config);

        // Initial status should be Disconnected
        assert!(matches!(manager.status().await, ConnectionStatus::Disconnected));
    }
}

