use ibxrust::{
    config::Config,
    connection::ConnectionManager,
    logging,
    Result,
};
use tracing::{info, error};
use std::process;

#[tokio::main]
async fn main() -> Result<()> {
    // Load configuration from environment
    let config = Config::from_env().unwrap_or_else(|e| {
        eprintln!("Failed to load configuration: {}", e);
        process::exit(1);
    });

    // Initialize logging
    logging::init_logging(&config).unwrap_or_else(|e| {
        eprintln!("Failed to initialize logging: {}", e);
        process::exit(1);
    });

    info!("Starting Interactive Brokers Trading App");
    logging::log_connection_info(&config);

    // Create connection manager
    let mut connection_manager = ConnectionManager::new(config.clone());

    // Connect to TWS
    match connection_manager.connect().await {
        Ok(_) => {
            info!("Successfully connected to TWS");

            // Perform health check
            if connection_manager.health_check().await? {
                info!("Connection health check passed");
            } else {
                error!("Connection health check failed");
            }

            // TODO: Implement main trading loop here
            info!("Application ready for trading operations");

            // For now, just wait a bit then disconnect
            tokio::time::sleep(tokio::time::Duration::from_secs(2)).await;

            // Disconnect cleanly
            connection_manager.disconnect().await?;
            info!("Application shutdown complete");
        }
        Err(e) => {
            error!("Failed to connect to TWS: {}", e);
            error!("Please ensure TWS or IB Gateway is running and API connections are enabled");
            error!("Check that the port {} is correct", config.tws_port);
            process::exit(1);
        }
    }

    Ok(())
}
